-- Creator Signal OS inbound deal triage schema
create extension if not exists pgcrypto;
create type public.deal_status as enum ('new','processing','needs_review','approved','rejected','archived');
create type public.severity as enum ('info','low','medium','high','critical');
create type public.draft_status as enum ('draft','approved','sent','discarded');
create table public.organizations (id uuid primary key default gen_random_uuid(), name text not null, created_at timestamptz not null default now());
create table public.users (id uuid primary key references auth.users(id) on delete cascade, organization_id uuid not null references public.organizations(id) on delete cascade, full_name text, role text not null default 'manager' check(role in ('owner','manager','coordinator','viewer')), created_at timestamptz not null default now());
create table public.creators (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, name text not null, handle text, email text, categories text[] not null default '{}', active boolean not null default true, created_at timestamptz not null default now());
create table public.rate_cards (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, creator_id uuid not null references public.creators(id) on delete cascade, name text not null, currency char(3) not null default 'USD', effective_from date not null, effective_to date, terms jsonb not null default '{}', created_at timestamptz not null default now());
create table public.inbound_deals (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, creator_id uuid references public.creators(id) on delete set null, provider text not null check(provider in ('resend','postmark','manual')), provider_event_id text not null, thread_id text, subject text, from_email text, received_at timestamptz not null, raw_text text, normalized_text text, status public.deal_status not null default 'new', extraction jsonb, extraction_confidence numeric(5,4), model_name text, prompt_version text, created_at timestamptz not null default now(), unique(organization_id,provider_event_id));
create table public.deal_terms (id uuid primary key default gen_random_uuid(), deal_id uuid not null unique references public.inbound_deals(id) on delete cascade, brand_name text, campaign_name text, fee numeric, currency char(3), deliverables jsonb not null default '[]', usage jsonb not null default '{}', whitelisting jsonb not null default '{}', exclusivity jsonb not null default '{}', term_start date, term_end date, payment_terms text, cancellation_terms text, evidence jsonb not null default '{}', unknown_fields text[] not null default '{}', created_at timestamptz not null default now());
create table public.redline_rules (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, creator_id uuid references public.creators(id) on delete cascade, name text not null, category text not null, severity public.severity not null default 'medium', rule jsonb not null, active boolean not null default true, created_at timestamptz not null default now());
create table public.counter_drafts (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, deal_id uuid not null references public.inbound_deals(id) on delete cascade, created_by uuid not null references public.users(id), subject text not null, body text not null, status public.draft_status not null default 'draft', model_name text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.deal_risks (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, deal_id uuid not null references public.inbound_deals(id) on delete cascade, rule_id uuid references public.redline_rules(id) on delete set null, category text not null, severity public.severity not null, explanation text not null, evidence jsonb not null default '{}', resolved boolean not null default false, created_at timestamptz not null default now());
create index deals_queue on public.inbound_deals(organization_id,status,received_at desc); create index creators_org on public.creators(organization_id); create index risks_deal on public.deal_risks(deal_id,severity);
create or replace function public.is_org_member(target uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.users where id=auth.uid() and organization_id=target) $$;
alter table public.organizations enable row level security; alter table public.users enable row level security; alter table public.creators enable row level security; alter table public.rate_cards enable row level security; alter table public.inbound_deals enable row level security; alter table public.deal_terms enable row level security; alter table public.redline_rules enable row level security; alter table public.counter_drafts enable row level security; alter table public.deal_risks enable row level security;
create policy org_read on public.organizations for select using(public.is_org_member(id));
create policy users_org on public.users for all using(public.is_org_member(organization_id)) with check(public.is_org_member(organization_id));
create policy creators_org on public.creators for all using(public.is_org_member(organization_id)) with check(public.is_org_member(organization_id));
create policy rates_org on public.rate_cards for all using(public.is_org_member(organization_id)) with check(public.is_org_member(organization_id));
create policy deals_org on public.inbound_deals for all using(public.is_org_member(organization_id)) with check(public.is_org_member(organization_id));
create policy terms_org on public.deal_terms for all using(exists(select 1 from public.inbound_deals d where d.id=deal_id and public.is_org_member(d.organization_id))) with check(exists(select 1 from public.inbound_deals d where d.id=deal_id and public.is_org_member(d.organization_id)));
create policy rules_org on public.redline_rules for all using(public.is_org_member(organization_id)) with check(public.is_org_member(organization_id));
create policy drafts_org on public.counter_drafts for all using(public.is_org_member(organization_id)) with check(public.is_org_member(organization_id));
create policy risks_org on public.deal_risks for all using(public.is_org_member(organization_id)) with check(public.is_org_member(organization_id));